// План specs/job-closed-date.md 1.1 (кейсы JC-01…JC-03). ПИШЕТ данные на проде: admin, компания «test».
// Создаёт работу «QA-closed auto #94c08102» (клиент «QA-quota client», техник Kirill), меняет её статус;
// в finally переводит работу в Cancelled (не висит в Completed и не влияет на выручку). Удаления работ в интерфейсе нет.
import { test, expect } from '@playwright/test';
import { ADMIN_STATE, setEnglish } from '../addresses/address-helpers';
import { setLanguage } from '../admin-plans/plans-helpers';
import { cellValue } from '../admin-plans/plans-read-helpers';
import { closedValue, jobRow, openJobsTab, parseClosed, setJobStatus } from './closed-helpers';

test.use({ storageState: ADMIN_STATE });

const JOB_TITLE = 'QA-closed auto #94c08102';
const QA_CLIENT = 'QA-quota client';
const TECH = 'Kirill';

test.describe('Работа: дата и время закрытия (#94c08102)', () => {
  test('Completed sets "Closed: <date time>" on the job and in the Completed list, reopening clears it, closing again sets a new time (EN + HE) #94c08102 @desktop @writes', async ({ page }) => {
    test.setTimeout(240_000);
    await setEnglish(page);
    const startedAt = Date.now();

    // 1. New Job: клиент QA (адрес подставляется), тип, описание, техник.
    await page.goto('/JobForm?action=new');
    const client = page.getByLabel('Client Name *');
    await client.pressSequentially('QA-quota', { delay: 20 });
    await page.getByRole('button').filter({ hasText: QA_CLIENT }).first().click();
    await expect(client).toHaveValue(QA_CLIENT);
    await expect(page.getByRole('textbox', { name: /^Address/ })).not.toHaveValue('');
    await page.getByRole('combobox').filter({ hasText: 'Select job type' }).click();
    await page.getByRole('option', { name: 'Repair', exact: true }).click();
    await page.getByLabel('Job Description').fill(JOB_TITLE);
    await page.getByRole('tabpanel', { name: 'Job Info' }).getByText('Select technicians').click();
    await page.getByRole('option', { name: new RegExp(`^${TECH}\\b`) }).click();
    await page.keyboard.press('Escape');
    await page.getByRole('button', { name: 'Create Job', exact: true }).click();
    await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
    const jobUrl = page.url().replace(/&tab=items/, '');
    const jobId = ((await page.getByText(/^#JOB-\d+$/).first().innerText()).trim()).slice(1);

    try {
      // 2. Completed → «Closed: <дата, время>» под статусом (источник: «מה רצוי» — לשמור ולהציג בעמוד העבודה).
      await setJobStatus(page, 'Completed');
      await expect(page.getByText('Closed:', { exact: true })).toBeVisible({ timeout: 20_000 });
      await page.goto(jobUrl); // сохранено на сервере, не только в форме
      await expect(closedValue(page)).toHaveText(/^[A-Z][a-z]{2} \d{1,2}, \d{4}, \d{1,2}:\d{2} (AM|PM)$/);
      const firstClosedText = (await closedValue(page).innerText()).trim();
      const firstClosed = parseClosed(firstClosedText);
      expect(firstClosed.getTime(), 'время закрытия — сейчас').toBeGreaterThanOrEqual(startedAt - 120_000);
      expect(firstClosed.getTime(), 'время закрытия — сейчас').toBeLessThanOrEqual(Date.now() + 120_000);

      // 3. Jobs → Completed: колонка «Closed» с тем же значением (источник: «מה רצוי» — כעמודה ברשימת העבודות).
      await openJobsTab(page, 'Completed');
      await expect(jobRow(page, jobId)).toBeVisible();
      expect(await cellValue(page, jobRow(page, jobId), 'Closed'), `Closed у ${jobId} в списке`).toBe(firstClosedText);

      // 4. Переоткрыть (In Progress) → «Closed» пропадает и после перезагрузки (комментарий программиста).
      await page.goto(jobUrl);
      await setJobStatus(page, 'In Progress');
      await expect(page.getByText('Closed:', { exact: true })).toBeHidden();
      await page.goto(jobUrl);
      await expect(page.getByText(/#JOB-\d+/).first()).toBeVisible();
      await expect(page.getByText('Closed:', { exact: true })).toBeHidden();

      // 5. Снова Completed → дата появляется заново, время не раньше первого закрытия.
      await setJobStatus(page, 'Completed');
      await page.goto(jobUrl);
      await expect(closedValue(page)).toHaveText(/\d{4}, \d{1,2}:\d{2} (AM|PM)$/);
      const secondClosed = parseClosed(await closedValue(page).innerText());
      expect(secondClosed.getTime(), 'повторное закрытие — новое время').toBeGreaterThanOrEqual(firstClosed.getTime());
      expect(secondClosed.getTime()).toBeLessThanOrEqual(Date.now() + 120_000);

      // 6. HE: подпись «נסגרה» на странице и заголовок колонки в списке (комментарий программиста).
      await setLanguage(page, 'he');
      await page.goto(jobUrl);
      await expect(page.getByText('נסגרה:', { exact: true })).toBeVisible();
      await openJobsTab(page, 'הסתיימו');
      await expect(jobRow(page, jobId)).toBeVisible();
      expect(await cellValue(page, jobRow(page, jobId), 'נסגרה'), `נסגרה у ${jobId}`).not.toBe('-');
    } finally {
      // Очистка: работа QA → Cancelled (EN-интерфейс).
      await setLanguage(page, 'en');
      await page.goto(jobUrl);
      await setJobStatus(page, 'Cancelled');
    }
  });
});
